1	import { useAuth } from '@/shared/hooks/useAuth';
2	import { Navigate } from 'react-router-dom';
3	import { useEffect, useState } from 'react';
4	import { useDeviceMode } from '@/shared/hooks/use-mobile';
5	
6	/**
7	 * Gerencia o redirecionamento da rota raiz (`/`).
8	 * Usuários autenticados e aprovados vão para `/dashboard`;
9	 * todos os demais são direcionados para `/auth`.
10	 */
11	export function RootRedirect() {
12	  const { user, loading, userProfile } = useAuth();
13	  const deviceMode = useDeviceMode();
14	  const [shouldRedirect, setShouldRedirect] = useState(false);
15	
16	  useEffect(() => {
17	    // Aguardar um pouco para garantir que a autenticação foi verificada
18	    const timer = setTimeout(() => {
19	      setShouldRedirect(true);
20	    }, 100);
21	
22	    return () => clearTimeout(timer);
23	  }, []);
24	
25	  // Mostrar loading enquanto verifica autenticação
26	  if (loading || !shouldRedirect) {
27	    return (
28	      <div className="min-h-screen flex items-center justify-center bg-background">
29	        <div className="flex flex-col items-center space-y-4">
30	          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
31	          <p className="text-muted-foreground">Carregando...</p>
32	        </div>
33	      </div>
34	    );
35	  }
36	
37	  // Desktop → /mia (chat principal). Mobile/Tablet → /dashboard (hub de navegação).
38	  if (
39	    user &&
40	    userProfile &&
41	    userProfile.approved &&
42	    !userProfile.needs_approval
43	  ) {
44	    const target = deviceMode === 'desktop' ? '/mia' : '/dashboard';
45	    return <Navigate to={target} replace />;
46	  }
47	
48	  // Se há um usuário mas precisa de aprovação, redirecionar para auth
49	  if (
50	    user &&
51	    userProfile &&
52	    (userProfile.needs_approval || !userProfile.approved)
53	  ) {
54	    return <Navigate to="/auth" replace />;
55	  }
56	
57	  // Para todos os outros casos (usuário não autenticado, sem perfil, etc.), redirecionar para auth
58	  return <Navigate to="/auth" replace />;
59	}
