1	// MiaContext — thin wrapper sobre o hook useMia de @/features/mia/model
2	// Toda a lógica foi movida para src/features/mia/model/useMia.ts (US-024)
3	//
4	// MIA 2.0 Glass-Box: adicionado MiaGlassBoxContext (paralelo, não modifica
5	// useMia.ts existente). Consumers do glass-box usam useMiaGlassBoxContext().
6	//
7	// Stream bridge (useMiaGlassBoxStreamBridge) é montado dentro do provider
8	// pra observar useMia state e popular watchLog em tempo real.
9	
10	import React, { createContext, useContext, ReactNode } from 'react';
11	import { useMia as useMiaHook, type UseMiaReturn, type MiaConversation } from '@/features/mia/model';
12	import { useMiaGlassBox, type UseMiaGlassBoxReturn } from '@/features/mia/model/useMiaGlassBox';
13	import { useMiaGlassBoxStreamBridge } from '@/features/mia/hooks/useMiaGlassBoxStreamBridge';
14	import { useMiaGlassBoxContextInjector } from '@/features/mia/hooks/useMiaGlassBoxContextInjector';
15	
16	// Re-export do tipo MiaConversation para consumers que o importam daqui
17	export type { MiaConversation };
18	
19	// ============================================================================
20	// CONTEXTS
21	// ============================================================================
22	
23	const MiaContext = createContext<UseMiaReturn | undefined>(undefined);
24	const MiaGlassBoxContext = createContext<UseMiaGlassBoxReturn | undefined>(undefined);
25	
26	// ============================================================================
27	// PROVIDER — combina hooks useMia + useMiaGlassBox + bridge
28	// ============================================================================
29	
30	/**
31	 * Inner — roda dentro dos providers pra conseguir consumir ambos os contexts.
32	 * Wireup das observações useMia → watchLog acontece aqui.
33	 */
34	function MiaProviderInner({ children }: { children: ReactNode }) {
35	  useMiaGlassBoxStreamBridge();
36	  useMiaGlassBoxContextInjector();
37	  return <>{children}</>;
38	}
39	
40	export function MiaProvider({ children }: { children: ReactNode }) {
41	  const miaValue = useMiaHook();
42	  const glassBoxValue = useMiaGlassBox();
43	  return (
44	    <MiaContext.Provider value={miaValue}>
45	      <MiaGlassBoxContext.Provider value={glassBoxValue}>
46	        <MiaProviderInner>{children}</MiaProviderInner>
47	      </MiaGlassBoxContext.Provider>
48	    </MiaContext.Provider>
49	  );
50	}
51	
52	// ============================================================================
53	// CONSUMER HOOKS
54	// ============================================================================
55	
56	export function useMia(): UseMiaReturn {
57	  const context = useContext(MiaContext);
58	  if (!context) throw new Error('useMia must be used within a MiaProvider');
59	  return context;
60	}
61	
62	/**
63	 * Hook para acessar estado do MIA 2.0 Glass-Box (Modo IA toggle, watch log,
64	 * Page Models, highlights, autonomia). Coexiste com useMia() — não substitui.
65	 *
66	 * Uso típico:
67	 *   const { miaModeEnabled, toggleMiaMode } = useMiaGlassBoxContext();
68	 */
69	export function useMiaGlassBoxContext(): UseMiaGlassBoxReturn {
70	  const context = useContext(MiaGlassBoxContext);
71	  if (!context) throw new Error('useMiaGlassBoxContext must be used within a MiaProvider');
72	  return context;
73	}
